-- Habit OS relational schema design
-- Target: MySQL 8.0.16+ / InnoDB. Design artifact only; not applied to a live DB.
-- UUIDs are generated by the application. All user-owned data is tenant-scoped.
-- Service layer MUST validate the authenticated user_id for every read/write.

SET NAMES utf8mb4;

CREATE TABLE users (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    external_subject VARCHAR(255) NULL,
    email VARCHAR(320) NULL,
    display_name VARCHAR(120) NOT NULL,
    account_status ENUM('active','disabled','deletion_pending') NOT NULL DEFAULT 'active',
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_users_external_subject (external_subject),
    KEY idx_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE user_preferences (
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    timezone VARCHAR(64) NOT NULL DEFAULT 'Africa/Cairo',
    week_starts_on TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '0=Sunday, 1=Monday ... 6=Saturday',
    locale VARCHAR(16) NOT NULL DEFAULT 'ar',
    date_format VARCHAR(32) NOT NULL DEFAULT 'YYYY-MM-DD',
    reminders_enabled BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Global reminder delivery switch; individual rules remain in habit_reminders',
    quiet_hours_start TIME NULL,
    quiet_hours_end TIME NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (user_id),
    CONSTRAINT fk_preferences_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT chk_preferences_week_start CHECK (week_starts_on BETWEEN 0 AND 6),
    CONSTRAINT chk_preferences_quiet_hours CHECK (
        (quiet_hours_start IS NULL AND quiet_hours_end IS NULL) OR
        (quiet_hours_start IS NOT NULL AND quiet_hours_end IS NOT NULL)
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Seed the default taxonomy per user; categories never own other domain records.
CREATE TABLE habit_categories (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    slug VARCHAR(80) NOT NULL,
    name VARCHAR(120) NOT NULL,
    sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_categories_user_id (user_id, id),
    UNIQUE KEY uq_categories_user_slug (user_id, slug),
    KEY idx_categories_user_active_order (user_id, is_active, sort_order),
    CONSTRAINT fk_categories_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habits (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(160) NOT NULL,
    habit_type ENUM('good','bad') NOT NULL,
    level ENUM('growth','maintenance','automatic','deferred') NOT NULL DEFAULT 'growth',
    status ENUM('active','paused','archived') NOT NULL DEFAULT 'active',
    start_date DATE NOT NULL,
    end_date DATE NULL COMMENT 'Inclusive; NULL means no planned end',
    why TEXT NULL,
    reward TEXT NULL,
    usual_triggers TEXT NULL,
    quit_reason TEXT NULL,
    recovery_plan TEXT NULL,
    archived_at TIMESTAMP(6) NULL,
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_habits_user_id (user_id, id),
    KEY idx_habits_user_status_level (user_id, status, level, deleted_at),
    KEY idx_habits_user_category (user_id, category_id),
    KEY idx_habits_user_dates (user_id, start_date, end_date),
    CONSTRAINT fk_habits_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_habits_category FOREIGN KEY (user_id, category_id)
        REFERENCES habit_categories(user_id, id) ON DELETE RESTRICT,
    CONSTRAINT chk_habits_end_date CHECK (end_date IS NULL OR end_date >= start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habit_versions (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    effective_from DATE NOT NULL COMMENT 'Inclusive local date',
    effective_to DATE NULL COMMENT 'Exclusive local date; NULL means current version',
    tracking_type ENUM('check','quantity','duration','avoidance') NOT NULL,
    schedule_type ENUM('daily','weekdays','times_per_period','interval','monthly','custom') NOT NULL,
    schedule_rule JSON NOT NULL,
    timezone VARCHAR(64) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NULL COMMENT 'Inclusive; NULL means no planned end',
    goal DECIMAL(12,3) NULL,
    minimum DECIMAL(12,3) NULL,
    unit VARCHAR(32) NULL,
    weight TINYINT UNSIGNED NOT NULL DEFAULT 1,
    priority ENUM('low','normal','high') NULL,
    preferred_time TIME NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_habit_version_start (user_id, habit_id, effective_from),
    UNIQUE KEY uq_habit_versions_user_id (user_id, id),
    KEY idx_habit_versions_lookup (user_id, habit_id, effective_from, effective_to),
    CONSTRAINT fk_habit_versions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_habit_versions_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE,
    CONSTRAINT chk_habit_version_dates CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT chk_habit_version_active_dates CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT chk_habit_version_weight CHECK (weight BETWEEN 1 AND 3),
    CONSTRAINT chk_habit_version_goal CHECK (
        (tracking_type IN ('quantity','duration') AND goal IS NOT NULL AND goal > 0
            AND (minimum IS NULL OR (minimum >= 0 AND minimum <= goal))) OR
        (tracking_type IN ('check','avoidance') AND goal IS NULL AND minimum IS NULL)
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habit_pause_periods (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NULL COMMENT 'Inclusive; NULL means not resumed yet',
    reason VARCHAR(500) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_pause_user_id (user_id, id),
    KEY idx_pause_habit_dates (user_id, habit_id, start_date, end_date),
    CONSTRAINT fk_pause_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_pause_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE,
    CONSTRAINT chk_pause_dates CHECK (end_date IS NULL OR end_date >= start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE books (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(240) NOT NULL,
    author VARCHAR(200) NULL,
    status ENUM('want_to_read','reading','on_hold','completed','abandoned') NOT NULL DEFAULT 'want_to_read',
    category VARCHAR(120) NULL,
    format VARCHAR(40) NULL,
    language VARCHAR(32) NULL,
    total_pages INT UNSIGNED NULL,
    pages_before_tracking INT UNSIGNED NOT NULL DEFAULT 0,
    start_date DATE NULL,
    end_date DATE NULL,
    rating DECIMAL(2,1) NULL,
    priority ENUM('low','normal','high') NULL,
    key_idea TEXT NULL,
    notes_quotes LONGTEXT NULL,
    cover_url VARCHAR(2048) NULL,
    external_url VARCHAR(2048) NULL,
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_books_user_id (user_id, id),
    KEY idx_books_user_status (user_id, status, deleted_at),
    KEY idx_books_user_name (user_id, name),
    CONSTRAINT fk_books_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT chk_books_pages CHECK (total_pages IS NULL OR total_pages >= 0),
    CONSTRAINT chk_books_rating CHECK (rating IS NULL OR (rating >= 1 AND rating <= 5)),
    CONSTRAINT chk_books_dates CHECK (start_date IS NULL OR end_date IS NULL OR end_date >= start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habit_books (
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    book_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    link_type ENUM('supports','related','reading_goal') NOT NULL DEFAULT 'related',
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (user_id, habit_id, book_id),
    KEY idx_habit_books_book (user_id, book_id),
    CONSTRAINT fk_habit_books_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_habit_books_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_habit_books_book FOREIGN KEY (user_id, book_id)
        REFERENCES books(user_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE reading_sessions (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    book_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Set NULL after an explicitly confirmed book purge; keep the title snapshot',
    read_on DATE NOT NULL,
    timezone_snapshot VARCHAR(64) NOT NULL,
    pages_read INT UNSIGNED NOT NULL DEFAULT 0,
    page_start INT UNSIGNED NULL,
    page_end INT UNSIGNED NULL,
    duration_seconds INT UNSIGNED NOT NULL DEFAULT 0,
    note TEXT NULL,
    book_title_snapshot VARCHAR(240) NULL,
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_reading_sessions_user_id (user_id, id),
    KEY idx_reading_sessions_book_day (user_id, book_id, read_on, deleted_at),
    CONSTRAINT fk_reading_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_reading_sessions_book FOREIGN KEY (user_id, book_id)
        REFERENCES books(user_id, id) ON DELETE RESTRICT,
    CONSTRAINT chk_reading_session_content CHECK (pages_read > 0 OR duration_seconds > 0),
    CONSTRAINT chk_reading_session_page_range CHECK (
        (page_start IS NULL AND page_end IS NULL) OR
        (page_start IS NOT NULL AND page_end IS NOT NULL AND page_end >= page_start)
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habit_daily_logs (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    local_date DATE NOT NULL,
    timezone_snapshot VARCHAR(64) NOT NULL,
    occurrence_key VARCHAR(96) NOT NULL,
    status ENUM('done','partial','missed','vacation','skipped') NOT NULL,
    actual DECIMAL(12,3) NULL,
    goal_snapshot DECIMAL(12,3) NULL,
    minimum_snapshot DECIMAL(12,3) NULL,
    unit_snapshot VARCHAR(32) NULL,
    weight_snapshot TINYINT UNSIGNED NULL,
    note TEXT NULL,
    trigger_text VARCHAR(500) NULL,
    book_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Optional reading context; not book ownership',
    book_title_snapshot VARCHAR(240) NULL COMMENT 'Retained context after the referenced book is purged',
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_daily_log_user_id (user_id, id),
    UNIQUE KEY uq_daily_log_occurrence (user_id, habit_id, local_date, occurrence_key),
    KEY idx_daily_logs_user_date (user_id, local_date, deleted_at),
    KEY idx_daily_logs_habit_date (user_id, habit_id, local_date, deleted_at),
    KEY idx_daily_logs_book_context (user_id, book_id),
    CONSTRAINT fk_daily_logs_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_daily_logs_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_daily_logs_book_context FOREIGN KEY (user_id, book_id)
        REFERENCES books(user_id, id) ON DELETE RESTRICT,
    CONSTRAINT chk_daily_log_actual CHECK (actual IS NULL OR actual >= 0),
    CONSTRAINT chk_daily_log_weight CHECK (weight_snapshot IS NULL OR weight_snapshot BETWEEN 1 AND 3),
    CONSTRAINT chk_daily_log_minimum CHECK (
        minimum_snapshot IS NULL OR minimum_snapshot >= 0
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habit_relapses (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    event_at_utc DATETIME(6) NOT NULL,
    local_date DATE NOT NULL,
    timezone_snapshot VARCHAR(64) NOT NULL,
    trigger_text VARCHAR(500) NULL,
    related_habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    severity TINYINT UNSIGNED NULL,
    what_happened TEXT NULL,
    plan_24h TEXT NULL,
    outcome TEXT NULL,
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_relapses_user_id (user_id, id),
    KEY idx_relapses_habit_event (user_id, habit_id, event_at_utc, deleted_at),
    CONSTRAINT fk_relapses_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_relapses_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_relapses_related_habit FOREIGN KEY (user_id, related_habit_id)
        REFERENCES habits(user_id, id) ON DELETE RESTRICT,
    CONSTRAINT chk_relapse_severity CHECK (severity IS NULL OR severity BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE journal_entries (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    entry_date DATE NOT NULL,
    entry_time TIME NULL,
    timezone_snapshot VARCHAR(64) NOT NULL,
    title VARCHAR(200) NOT NULL,
    intention TEXT NULL,
    top_3 JSON NULL,
    mood TINYINT UNSIGNED NULL,
    energy TINYINT UNSIGNED NULL,
    gratitude TEXT NULL,
    win TEXT NULL,
    learning TEXT NULL,
    worries TEXT NULL,
    tomorrow_plan TEXT NULL,
    body LONGTEXT NULL,
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_journal_user_id (user_id, id),
    KEY idx_journal_user_date (user_id, entry_date, deleted_at),
    KEY idx_journal_user_updated (user_id, updated_at),
    CONSTRAINT fk_journal_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT chk_journal_mood CHECK (mood IS NULL OR mood BETWEEN 1 AND 5),
    CONSTRAINT chk_journal_energy CHECK (energy IS NULL OR energy BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE journal_tags (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(80) NOT NULL,
    normalized_name VARCHAR(80) NOT NULL,
    color VARCHAR(16) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_journal_tags_user_id (user_id, id),
    UNIQUE KEY uq_journal_tags_user_name (user_id, normalized_name),
    CONSTRAINT fk_journal_tags_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE journal_habits (
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    journal_entry_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    relation_note VARCHAR(500) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (user_id, journal_entry_id, habit_id),
    KEY idx_journal_habits_habit (user_id, habit_id),
    CONSTRAINT fk_journal_habits_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_journal_habits_entry FOREIGN KEY (user_id, journal_entry_id)
        REFERENCES journal_entries(user_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_journal_habits_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE journal_entry_tags (
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    journal_entry_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    tag_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (user_id, journal_entry_id, tag_id),
    KEY idx_journal_entry_tags_tag (user_id, tag_id),
    CONSTRAINT fk_journal_entry_tags_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_journal_entry_tags_entry FOREIGN KEY (user_id, journal_entry_id)
        REFERENCES journal_entries(user_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_journal_entry_tags_tag FOREIGN KEY (user_id, tag_id)
        REFERENCES journal_tags(user_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE weekly_focus (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    what_worked TEXT NULL,
    what_failed TEXT NULL,
    rating TINYINT UNSIGNED NULL,
    next_week_adjustment TEXT NULL,
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_weekly_focus_user_id (user_id, id),
    UNIQUE KEY uq_weekly_focus_user_start (user_id, start_date),
    KEY idx_weekly_focus_user_range (user_id, start_date, end_date, deleted_at),
    CONSTRAINT fk_weekly_focus_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT chk_weekly_focus_range CHECK (end_date >= start_date),
    CONSTRAINT chk_weekly_focus_rating CHECK (rating IS NULL OR rating BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE weekly_focus_habits (
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    weekly_focus_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    position TINYINT UNSIGNED NOT NULL DEFAULT 1,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (user_id, weekly_focus_id, habit_id),
    UNIQUE KEY uq_week_focus_position (user_id, weekly_focus_id, position),
    KEY idx_week_focus_habits_habit (user_id, habit_id),
    CONSTRAINT fk_week_focus_habits_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_week_focus_habits_week FOREIGN KEY (user_id, weekly_focus_id)
        REFERENCES weekly_focus(user_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_week_focus_habits_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE achievements (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(160) NOT NULL,
    condition_type ENUM('clean_days','total_quantity','completed_days') NOT NULL,
    condition_value DECIMAL(12,3) NOT NULL,
    current_value DECIMAL(12,3) NOT NULL DEFAULT 0 COMMENT 'Recomputable cache; never directly edited by user',
    is_achieved BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Derived cache',
    achieved_at TIMESTAMP(6) NULL COMMENT 'First achieved timestamp, reconciled after historical correction',
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    archived_at TIMESTAMP(6) NULL,
    deleted_at TIMESTAMP(6) NULL,
    purge_after TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_achievements_user_id (user_id, id),
    KEY idx_achievements_user_state (user_id, enabled, is_achieved, deleted_at),
    CONSTRAINT fk_achievements_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT chk_achievements_condition_value CHECK (condition_value > 0),
    CONSTRAINT chk_achievements_current_value CHECK (current_value >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Zero-or-one habit scope per achievement; deleting a habit removes only the link.
CREATE TABLE achievement_habits (
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    achievement_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (user_id, achievement_id),
    UNIQUE KEY uq_achievement_habit_link (user_id, achievement_id, habit_id),
    KEY idx_achievement_habits_habit (user_id, habit_id),
    CONSTRAINT fk_achievement_habits_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_achievement_habits_achievement FOREIGN KEY (user_id, achievement_id)
        REFERENCES achievements(user_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_achievement_habits_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habit_relations (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    source_habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    target_habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    relation_type ENUM('related','alternative','replacement','supports') NOT NULL,
    is_directed BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_habit_relations_user_pair_type (user_id, source_habit_id, target_habit_id, relation_type),
    KEY idx_habit_relations_target (user_id, target_habit_id),
    CONSTRAINT fk_habit_relations_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_habit_relations_source FOREIGN KEY (user_id, source_habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_habit_relations_target FOREIGN KEY (user_id, target_habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE,
    CONSTRAINT chk_habit_relation_not_self CHECK (source_habit_id <> target_habit_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE habit_reminders (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    habit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    local_time TIME NOT NULL,
    timezone_override VARCHAR(64) NULL,
    days_of_week JSON NULL COMMENT 'NULL means use the habit schedule; otherwise explicit weekdays',
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    snooze_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 10,
    quiet_hours_respected BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_habit_reminders_user_id (user_id, id),
    KEY idx_habit_reminders_due (user_id, habit_id, enabled, local_time),
    CONSTRAINT fk_habit_reminders_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_habit_reminders_habit FOREIGN KEY (user_id, habit_id)
        REFERENCES habits(user_id, id) ON DELETE CASCADE,
    CONSTRAINT chk_reminder_snooze CHECK (snooze_minutes <= 1440)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE audit_events (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    entity_type VARCHAR(64) NOT NULL,
    entity_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    action ENUM('created','updated','archived','restored','soft_deleted','purged','exported') NOT NULL,
    changed_fields JSON NULL COMMENT 'Names/filtered metadata only; never journal body or secret values',
    request_id VARCHAR(96) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    KEY idx_audit_user_time (user_id, created_at),
    KEY idx_audit_entity (user_id, entity_type, entity_id, created_at),
    CONSTRAINT fk_audit_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Application transaction rules not expressible as a portable single CHECK:
-- 1) No overlapping habit_versions or pause periods; lock the habit/user row and verify.
-- 2) habit_relapses.habit_id must reference a habit whose habit_type='bad'.
-- 3) Validate ownership, schedule_rule JSON shape, actual/status against the active version,
--    and relation cycles in the trusted service layer on every write.
-- 4) Habit hard-delete with history requires explicit user choice; RESTRICT on daily logs/relapses
--    prevents accidental loss. User-account purge deletes dependent data in reverse FK order.
-- 5) For a permanent book delete, first set daily_logs.book_id=NULL and reading_sessions.book_id=NULL,
--    copying books.name into reading_sessions.book_title_snapshot, then delete the book.
-- 6) For a historical edit/delete, recalculate affected streaks/clean-days/achievements atomically.
-- 7) Soft-deleted records stay in place for restore; queries must exclude deleted_at IS NOT NULL by default.
